Funcion leap <- IsLeapYear(anio Como Entero)
  Definir leap Como Logico;
  leap <- (anio mod 4 = 0 Y anio mod 100 <> 0) O anio mod 400 = 0;
FinFuncion

Algoritmo Main
  Definir anio Como Entero;
  Leer anio;
  Si IsLeapYear(anio) Entonces
    Escribir "Leap year";
  Sino
    Escribir "Not a leap year";
  FinSi
FinAlgoritmo
